"""Convert a .tflite model into a C++ source file that firmware can link.

Usage: python tools/tflite_to_c.py models/person_detect.tflite src/ai/model_data.cpp
"""
import sys
from pathlib import Path

src, dst = Path(sys.argv[1]), Path(sys.argv[2])
data = src.read_bytes()
lines = []
for i in range(0, len(data), 16):
    lines.append("  " + ", ".join(f"0x{b:02x}" for b in data[i:i + 16]) + ",")
dst.parent.mkdir(parents=True, exist_ok=True)
dst.write_text(
    "// Generated by tools/tflite_to_c.py from " + src.name + " -- do not edit by hand.\n"
    '#include "model_data.h"\n\n'
    "alignas(16) const unsigned char g_model_data[] = {\n" + "\n".join(lines) + "\n};\n"
    f"const unsigned int g_model_data_len = {len(data)};\n",
    encoding="utf-8",
)
print(f"wrote {dst} ({len(data)} bytes)")
